head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst60201";
scwin.kosdaqSeg = null;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — kwd

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.kosdaqSeg = $c.util.getComponent('kosdaqSeg');
        scwin.init_rowCopy();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst60201.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_kwd", fn: function () { return String(String((dma_pageContext.get("kwd") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function () {
    let kwd = (String(((dma_pageContext.get("kwd") ?? "")) == null ? '' : ((dma_pageContext.get("kwd") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("kwd") ?? "")) == null ? '' : ((dma_pageContext.get("kwd") ?? ""))));
    if ("" === kwd) {
        kwd = "AKCKwd";
    }
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("method", "searchCorpList");
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("forward", "corpList");
    const comnm = (scwin.openerScwin()[kwd] && (scwin.openerScwin()[kwd]).getValue ? (scwin.openerScwin()[kwd]).getValue() : ((scwin.opener().getComponentById(kwd) || {}).getValue ? scwin.opener().getComponentById(kwd).getValue() : ''));
    if (comnm !== "") {
        $c.util.getComponent('ipt_corpNameTmp').setValue(comnm);
        scwin.reflectCorpName();
    }
    await scwin.fnSearchInit();
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        $(this).find("input:radio[name=rd_marketType]").click(function() {
                scwin.fnShowKosdaqSeg($(this));
        });
        await scwin.init();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst60201.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name searchForm_onsubmit
 * @description searchForm onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.searchForm_onsubmit = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst60201.searchForm_onsubmit' }); }
};

